const express = require('express');
const http = require('http');
const httpProxy = require('http-proxy');

const app = express();
const proxy = httpProxy.createProxyServer({});

// Internal admin service - only accessible via proxy
const adminApp = express();
adminApp.post('/admin/delete-user', (req, res) => {
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    const { userId } = JSON.parse(body);
    // Performs destructive action - deletes user from DynamoDB
    const AWS = require('aws-sdk');
    const dynamodb = new AWS.DynamoDB.DocumentClient();
    dynamodb.delete({
      TableName: 'Users',
      Key: { userId }
    }).promise().then(() => {
      res.json({ deleted: true, userId });
    }).catch(err => {
      res.status(500).json({ error: err.message });
    });
  });
});

adminApp.post('/admin/grant-role', (req, res) => {
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    const { userId, role } = JSON.parse(body);
    const AWS = require('aws-sdk');
    const dynamodb = new AWS.DynamoDB.DocumentClient();
    dynamodb.update({
      TableName: 'Users',
      Key: { userId },
      UpdateExpression: 'SET #r = :role',
      ExpressionAttributeNames: { '#r': 'role' },
      ExpressionAttributeValues: { ':role': role }
    }).promise().then(() => {
      res.json({ granted: true, userId, role });
    }).catch(err => {
      res.status(500).json({ error: err.message });
    });
  });
});

// Public-facing routes
app.use('/api/public', (req, res) => {
  res.json({ status: 'ok', time: Date.now() });
});

// Proxy to internal admin - relies on front-end ALB for auth
// The proxy does NOT validate Transfer-Encoding vs Content-Length
app.use('/internal', (req, res) => {
  proxy.web(req, res, { target: 'http://127.0.0.1:3001' });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).send('OK');
});

// Start servers
const frontServer = http.createServer(app);
frontServer.listen(3000, () => {
  console.log('Front proxy listening on 3000');
});

const adminServer = http.createServer(adminApp);
adminServer.listen(3001, () => {
  console.log('Admin service listening on 3001');
});

// Note: Node.js http.createServer with default settings
// does NOT reject ambiguous Transfer-Encoding headers.
// This allows CL.TE smuggling when behind a proxy that
// prioritizes Content-Length over Transfer-Encoding.
